// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.screensimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.layout.widthimport androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.collectAsStateimport androidx.compose.runtime.getValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.components.GlassPanelimport com.roshan.persona.ui.components.LayerBadgeimport com.roshan.persona.ui.state.UiStateProviderimport com.roshan.persona.ui.theme.brainLayerColor/** * Brain Activity overlay — shows the 6-layer cascade + real-time stats. * * Wired to [UiStateProvider]: *   - brainHealthPercent, brainLayerActivity (per-layer activity) *   - lastBrainLatencyMs, lastBrainCostUsd, lastBrainTokens, lastBrainLayerHandled *   - memoryCount, episodicCount, semanticCount */@Composablefun BrainActivitySheet(    stateProvider: UiStateProvider,    modifier: Modifier = Modifier,) {    val brainHealth by stateProvider.brainHealthPercent.collectAsState()    val layerActivity by stateProvider.brainLayerActivity.collectAsState()    val latency by stateProvider.lastBrainLatencyMs.collectAsState()    val cost by stateProvider.lastBrainCostUsd.collectAsState()    val tokens by stateProvider.lastBrainTokens.collectAsState()    val lastLayer by stateProvider.lastBrainLayerHandled.collectAsState()    val memCount by stateProvider.memoryCount.collectAsState()    val episodic by stateProvider.episodicCount.collectAsState()    val semantic by stateProvider.semanticCount.collectAsState()    Column(        modifier = modifier            .fillMaxWidth()            .background(                color = MaterialTheme.colorScheme.surface,                shape = RoundedCornerShape(topStart = 24.dp, topEnd = 24.dp),            )            .padding(20.dp),    ) {        Text(            text = "Brain Activity",            style = MaterialTheme.typography.headlineLarge,            fontWeight = FontWeight.Bold,            color = MaterialTheme.colorScheme.onSurface,        )        Spacer(modifier = Modifier.size(16.dp))        // Cascade visualization        GlassPanel(title = "6-Layer Cascade") {            val layers = listOf("L0", "L1", "L2", "L3", "L4", "L5")            val labels = mapOf(                "L0" to "Intent",                "L1" to "Rule",                "L2" to "Skill",                "L3" to "Local LLM",                "L4" to "Cloud LLM",                "L5" to "Agentic",            )            layers.forEach { layer ->                val activity = layerActivity[layer] ?: 0f                val color = brainLayerColor(layer)                val isActive = lastLayer == labels[layer] ||                    lastLayer?.equals(labels[layer], ignoreCase = true) == true                Row(                    modifier = Modifier                        .fillMaxWidth()                        .padding(vertical = 4.dp),                    verticalAlignment = Alignment.CenterVertically,                ) {                    LayerBadge(layerName = layer)                    Spacer(modifier = Modifier.size(8.dp))                    Text(                        text = labels[layer] ?: layer,                        style = MaterialTheme.typography.bodyMedium,                        color = if (isActive) color else MaterialTheme.colorScheme.onSurface,                        fontWeight = if (isActive) FontWeight.SemiBold else FontWeight.Normal,                    )                    Spacer(modifier = Modifier.weight(1f))                    // Activity bar                    androidx.compose.foundation.layout.Box(                        modifier = Modifier                            .width(80.dp)                            .size(height = 6.dp, width = 80.dp)                            .background(                                color = MaterialTheme.colorScheme.surfaceVariant,                                shape = RoundedCornerShape(3.dp),                            ),                    ) {                        androidx.compose.foundation.layout.Box(                            modifier = Modifier                                .size(width = 80.dp * activity, height = 6.dp)                                .background(                                    color = color,                                    shape = RoundedCornerShape(3.dp),                                ),                        )                    }                    Spacer(modifier = Modifier.size(8.dp))                    Text(                        text = "${(activity * 100).toInt()}%",                        style = MaterialTheme.typography.labelSmall,                        color = MaterialTheme.colorScheme.onSurfaceVariant,                    )                }            }        }        Spacer(modifier = Modifier.size(16.dp))        // Last request trace        GlassPanel(title = "Last Request") {            Text(                text = "Layer: $lastLayer",                style = MaterialTheme.typography.bodyMedium,                color = MaterialTheme.colorScheme.onSurface,            )            Text(                text = "Latency: ${latency}ms",                style = MaterialTheme.typography.bodyMedium,                color = MaterialTheme.colorScheme.onSurface,            )            Text(                text = "Tokens: $tokens",                style = MaterialTheme.typography.bodyMedium,                color = MaterialTheme.colorScheme.onSurface,            )            Text(                text = "Cost: $%.4f".format(cost),                style = MaterialTheme.typography.bodyMedium,                color = MaterialTheme.colorScheme.onSurface,            )        }        Spacer(modifier = Modifier.size(16.dp))        // Memory stats        GlassPanel(title = "Memory") {            Text(                text = "Total: $memCount · Episodic: $episodic · Semantic: $semantic",                style = MaterialTheme.typography.bodyMedium,                color = MaterialTheme.colorScheme.onSurface,            )        }    }}